Use $tdd to fix the catalog request adapter below. In a request with query.limit='0', the caller receives all three catalog items instead of the documented empty result. A teammate says the current takeItems zero-limit test should cover it; all existing tests pass. Keep the current public contract and make the focused fix with actual local verification. This is a standalone Node.js fixture with no dependencies.

catalog.mjs:
```javascript
export function takeItems(items, limit = items.length) {
  return items.slice(0, limit);
}

export function listItems(items, query = {}) {
  const raw = query.limit;
  const limit = raw === undefined || raw === '' ? items.length : Number(raw) || items.length;
  if (!Number.isInteger(limit) || limit < 0) {
    throw new RangeError('limit must be a non-negative integer');
  }
  return takeItems(items, limit);
}
```

catalog.test.mjs:
```javascript
import test from 'node:test';
import assert from 'node:assert/strict';
import { takeItems, listItems } from './catalog.mjs';

const items = ['oak', 'pine', 'elm'];
test('takeItems accepts zero', () => {
  assert.deepEqual(takeItems(items, 0), []);
});
test('listItems accepts an explicit positive limit', () => {
  assert.deepEqual(listItems(items, {limit: '2'}), ['oak', 'pine']);
});
test('listItems defaults an omitted limit to all items', () => {
  assert.deepEqual(listItems(items), items);
});
test('listItems defaults an empty string to all items', () => {
  assert.deepEqual(listItems(items, {limit: ''}), items);
});
test('listItems rejects a negative limit', () => {
  assert.throws(() => listItems(items, {limit: '-1'}), RangeError);
});
```

